// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Setup: deploy with caller = this (DAO initially set to this)
        // The reference and bug differ in endConfiguration: reference sets configured=true, bug sets false.
        // Since configured starts false, and we never call endConfiguration (or call it before the action),
        // we can trigger the difference by calling endConfiguration AFTER assertGovernanceApproved (which doesn't change configured directly).
        // But the diff says "after a call to assertGovernanceApproved, the value of configured differs".
        // This is because the bug changes endConfiguration to set false, but the reference sets true.
        // To make them diverge, we call endConfiguration first (this is the only place the change matters):
        // In reference, configured becomes true; in bug, it stays false (since it sets false but it was already false).
        // Then we call assertGovernanceApproved, after which the comparison holds.
        // However the diff states that after assertGovernanceApproved, configured differs.
        // We need a scenario where assertGovernanceApproved executes and then configured is different.
        // Since assertGovernanceApproved does not change configured, the difference must come from a prior endConfiguration call.
        // So: first call endConfiguration, then call assertGovernanceApproved. In reference, configured=true; in bug, configured=false.

        // Step 1: call endConfiguration (as this, the DAO)
        // We need to be the DAO. The DAO is address(this) from constructor.
        c.endConfiguration();

        // Now we need to set up for assertGovernanceApproved: have enough tokens, approve, ensure governance asset is set.
        // But since we only care about the state of configured after the call, we can make assertGovernanceApproved revert or succeed.
        // To make it succeed, we need to satisfy the transferFrom condition. That requires an ERC20 token at flashGovernanceConfig.asset.
        // For simplicity, we can set the asset to a mock we deploy, but that would need a contract. We'll use address(this) as a dummy token that will revert on transferFrom (since it doesn't have a balance), causing assertGovernanceApproved to revert.
        // The divergence in configured after assertGovernanceApproved will still hold: before the call, configured was true (ref) vs false (bug); after the revert, it remains the same.
        // So we just call assertGovernanceApproved and then check configured.

        // But we need to pass flashEnabled modifier: msg.sender must be DAO or governed[msg.sender]=true.
        // DAO is address(this). So we can call as this.

        // Call assertGovernanceApproved (will revert because no token, but that's fine)
        vm.prank(address(this));
        try c.assertGovernanceApproved(address(this), address(0x123), false) {
            // should not reach here
        } catch {
            // expected revert
        }

        // Now check configured
        bool configuredAfter = c.configured();
        // In reference, endConfiguration set configured=true, so true
        // In bug, endConfiguration set configured=false, so false
        // Therefore reference satisfied true, bug breaks (false)
        assertTrue(configuredAfter, "configured should be true in reference, false in bug");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Step 1: set DAO to something else so that setDAO below can be called by a non-DAO sender
        vm.prank(address(this));
        c.setDAO(address(0x1));
        // Step 2: call endConfiguration to finalize configuration (in reference, configured becomes true)
        c.endConfiguration();
        // Step 3: call setDAO with a non-DAO sender while configured is true - this will revert in reference but succeed in bug (different configured values don't matter here)
        // Instead, directly observe the configured state
        bool refConfigured = c.configured();
        // In the reference, configured is true; in bug, configured is false
        // Use a revert difference: call assertGovernanceApproved with a governance approval that requires configured to be true
        // First, set up the flash governance config so that the transfer succeeds
        address flanToken = address(0xdead);
        vm.store(address(c), keccak256(abi.encode(uint256(0), uint256(0))), bytes32(uint256(1))); // fake balance
        // Actually, we can just check the revert of assertGovernanceApproved by a simple call
        // In reference, configured=true and we need a successful proposal or governance approval
        // In bug, configured=false so assertGovernanceApproved will revert due to other reasons
        bool ok;
        try c.assertGovernanceApproved(address(this), address(0x2), false) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference (configured=true) will revert because no flash governance config set, so ok=false
        // The bug (configured=false) will also revert because assertGovernanceApproved still has other checks
        // This doesn't diverge. Let's find a different path.
        // Instead, use the fact that setDAO in reference will revert when configured=true and sender != DAO, but in bug it won't because configured=false
        // Reset the state
        c = new C(address(this));
        vm.prank(address(this));
        c.setDAO(address(0x1));
        c.endConfiguration();
        // Now configured is true in reference, false in bug
        // Try to call setDAO with address(this) - in reference it should revert (because configured and sender != DAO)
        // In bug it should succeed (because configured is false)
        vm.prank(address(this));
        try c.setDAO(address(0x3)) {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference, ok=false; in bug, ok=true
        assertTrue(ok == false, "Bug: setDAO should have reverted because configured is true");
    }
}

