pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address alice = address(0x1234);
        // After deployment, DAO is address(this). Now call assertGovernanceApproved from alice.
        // First, we need to make alice "governed" or be the DAO to pass the flashEnabled modifier.
        // For simplicity, set alice as governed:
        // But governed mapping is only settable via onlySuccessfulProposal, so we need to call setGoverned.
        // Since configured is false initially, onlySuccessfulProposal will pass automatically.
        address[] memory targets = new address[](1);
        targets[0] = alice;
        bool[] memory isGoverned = new bool[](1);
        isGoverned[0] = true;
        c.setGoverned(targets, isGoverned);

        // Now call assertGovernanceApproved from alice (it will revert due to missing allowance/balance, but we capture revert boolean)
        vm.prank(alice);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("assertGovernanceApproved(address,address,bool)", alice, address(c), false));

        // The important thing: now check DAO getter
        address daoAfter = c.DAO();
        // Reference: DAO should be address(this) (unchanged). Bug: DAO becomes alice.
        assertTrue(daoAfter == address(this), "DAO should be test contract in reference, but check condition");
    }
}

